android.extraProguardRules:
# expo-notifications ships its own proguard-rules.pro but does NOT wire it as a consumerProguardFiles entry, so it is never applied to a minified build unless repeated here — without this, R8 can strip/rename its internal scheduling/trigger classes (e.g. DailyTrigger, used by the daily finance-reminder notifications), which are round-tripped through AlarmManager PendingIntent extras by class name.
-keep class expo.modules.notifications.** { *; }
# Custom native module (modules/expo-notification-listener) — defensively kept in full so its NotificationListenerService (instantiated by Android via the class name in its AndroidManifest.xml) can't be broken by a rename.
-keep class com.sithija.snapbudget.notificationlistener.** { *; }
